import{_ as t,a,c as n,ac as o}from"./chunks/framework.BSuaGltH.js";const u=JSON.parse('{"title":"第四册：流利英语 · Lesson 30 Exploring the sea-floor","description":"学习 介词 + which 的关系从句，配有原创例句、重点词汇和带解析的自测。","frontmatter":{"title":"第四册：流利英语 · Lesson 30 Exploring the sea-floor","description":"学习 介词 + which 的关系从句，配有原创例句、重点词汇和带解析的自测。","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"路线与能力起点","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"新概念英语经典版第4册课时","summary":"学习 介词 + which 的关系从句，配有原创例句、重点词汇和带解析的自测。","status":"active","related":[{"title":"程序员英语 08：一次完整的阅读与协作实战","link":"/life/english/programmer/practice","kind":"读写与对话练习","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语","link":"/life/english/new-concept/book-2/unit-01/vocabulary","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 第17–24课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-02","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 字母索引与第1–16课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-01","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 复习与自测","link":"/life/english/new-concept/book-2/unit-01/review","kind":"读写与对话练习","scope":"general","audience":"general"}],"prev":{"text":"第四册：流利英语 · Lesson 29 The hovercraft","link":"/life/english/new-concept/book-4/unit-04/lesson-029"},"next":{"text":"第四册：流利英语 · Lesson 31 The sculptor speaks","link":"/life/english/new-concept/book-4/unit-04/lesson-031"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第四册：流利英语 · Lesson 29 The hovercraft","link":"/life/english/new-concept/book-4/unit-04/lesson-029"},"next":{"text":"第四册：流利英语 · Lesson 31 The sculptor speaks","link":"/life/english/new-concept/book-4/unit-04/lesson-031"}},"headers":[],"relativePath":"life/english/new-concept/book-4/unit-04/lesson-030.md","filePath":"life/english/new-concept/book-4/unit-04/lesson-030.md"}'),r={name:"life/english/new-concept/book-4/unit-04/lesson-030.md"};function i(s,e,l,h,d,c){return a(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="第四册-流利英语-·-lesson-30-exploring-the-sea-floor" tabindex="-1">第四册：流利英语 · Lesson 30 Exploring the sea-floor <a class="header-anchor" href="#第四册-流利英语-·-lesson-30-exploring-the-sea-floor" aria-label="Permalink to &quot;第四册：流利英语 · Lesson 30 Exploring the sea-floor&quot;">​</a></h1><p><a href="/life/english/new-concept/overview">系列目录</a> · <a href="/life/english/new-concept/book-4/contents">本册目录</a> · <a href="/life/english/new-concept/book-4/unit-04/overview">单元 4</a></p><h2 id="学习目标与内容导读" tabindex="-1">学习目标与内容导读 <a class="header-anchor" href="#学习目标与内容导读" aria-label="Permalink to &quot;学习目标与内容导读&quot;">​</a></h2><p>从海底探索主题练习如何描述难以直接观察的对象。将仪器返回的信号、形成的图像与研究者提出的解释分层叙述，注意测量分辨率和覆盖范围的限制。重点使用介词加关系代词说明设备工作的条件，避免把关系从句写成缺少介词的不完整结构。</p><p>本课以主题阅读带动语言分析，学习重点如下。</p><h2 id="单词与搭配" tabindex="-1">单词与搭配 <a class="header-anchor" href="#单词与搭配" aria-label="Permalink to &quot;单词与搭配&quot;">​</a></h2><table tabindex="0"><thead><tr><th>单词</th><th>音标</th><th>词性</th><th>本页义项</th><th>搭配</th></tr></thead><tbody><tr><td>depth</td><td>/depθ/</td><td>n.</td><td>深度</td><td>at a great depth</td></tr><tr><td>sonar</td><td>/ˈsəʊnɑː/</td><td>n.</td><td>声呐</td><td>a sonar image</td></tr><tr><td>terrain</td><td>/təˈreɪn/</td><td>n.</td><td>地形</td><td>underwater terrain</td></tr><tr><td>resolution</td><td>/ˌrezəˈluːʃən/</td><td>n.</td><td>分辨率</td><td>image resolution</td></tr></tbody></table><h2 id="短语与句型" tabindex="-1">短语与句型 <a class="header-anchor" href="#短语与句型" aria-label="Permalink to &quot;短语与句型&quot;">​</a></h2><ul><li>map out — 绘制分布图</li><li>below the surface — 在表面以下</li></ul><h2 id="语法讲解-介词-which-的关系从句" tabindex="-1">语法讲解：介词 + which 的关系从句 <a class="header-anchor" href="#语法讲解-介词-which-的关系从句" aria-label="Permalink to &quot;语法讲解：介词 + which 的关系从句&quot;">​</a></h2><p>the depth at which the instrument operates 中 which 指 depth，at 来自 operate at a depth。正式表达可把介词放在关系代词前；较口语的限制性从句可把介词放句尾，如 the depth which it operates at。介词后的关系代词不能用 that，也不能省略。选择介词应看动词或名词搭配，不能见到地点就一律用 in；pressure 常搭配 under。</p><h2 id="原创例句与结构分析" tabindex="-1">原创例句与结构分析 <a class="header-anchor" href="#原创例句与结构分析" aria-label="Permalink to &quot;原创例句与结构分析&quot;">​</a></h2><blockquote><p>The pressure under which the sensor operates must be recorded.</p></blockquote><p>必须记录传感器工作时所处的压力。</p><p>under which 修饰 pressure；主句主语是整个名词短语，must be recorded 为谓语。</p><h2 id="易错辨析" tabindex="-1">易错辨析 <a class="header-anchor" href="#易错辨析" aria-label="Permalink to &quot;易错辨析&quot;">​</a></h2><p>under that the sensor operates 不成立；介词前置的关系结构用 which。</p><h2 id="听说训练" tabindex="-1">听说训练 <a class="header-anchor" href="#听说训练" aria-label="Permalink to &quot;听说训练&quot;">​</a></h2><p>把 under which the sensor operates 作为一个修饰意群；主句重读 pressure 与 recorded，保持长句主干可听见。</p><h2 id="读写训练" tabindex="-1">读写训练 <a class="header-anchor" href="#读写训练" aria-label="Permalink to &quot;读写训练&quot;">​</a></h2><h3 id="阅读材料-本站原创" tabindex="-1">阅读材料（本站原创） <a class="header-anchor" href="#阅读材料-本站原创" aria-label="Permalink to &quot;阅读材料（本站原创）&quot;">​</a></h3><p>The report lists the depth at which each image was taken. A ridge appears along the eastern edge. Smaller features remain uncertain because the resolution is limited.</p><h3 id="表达任务" tabindex="-1">表达任务 <a class="header-anchor" href="#表达任务" aria-label="Permalink to &quot;表达任务&quot;">​</a></h3><p>用三句介绍一张虚构海底图：测量条件、图像所示、尚未确定的细节。</p><details class="details custom-block"><summary>写作提示与点评</summary><p>条件、图形观察和分辨率限制分开表达，不把图像当作无误的直接观看。</p></details><h2 id="课后自测" tabindex="-1">课后自测 <a class="header-anchor" href="#课后自测" aria-label="Permalink to &quot;课后自测&quot;">​</a></h2><h3 id="练习-1" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1" aria-label="Permalink to &quot;练习 1&quot;">​</a></h3><p>填空：the depth ___ which the camera was tested。</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> at</p><p><strong>解析：</strong> 在某深度使用 at a depth。</p></details><h3 id="练习-2" tabindex="-1">练习 2 <a class="header-anchor" href="#练习-2" aria-label="Permalink to &quot;练习 2&quot;">​</a></h3><p>示例中 must be recorded 的主语核心是什么？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> pressure</p><p><strong>解析：</strong> sensor 是关系从句内部主语。</p></details><h3 id="练习-3" tabindex="-1">练习 3 <a class="header-anchor" href="#练习-3" aria-label="Permalink to &quot;练习 3&quot;">​</a></h3><p>将 the conditions which it works under 改为介词前置形式。</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> the conditions under which it works</p><p><strong>解析：</strong> under 移到 which 前。</p></details><h2 id="复习导航" tabindex="-1">复习导航 <a class="header-anchor" href="#复习导航" aria-label="Permalink to &quot;复习导航&quot;">​</a></h2><p>本课重点：介词 + which 的关系从句。复习时先遮住答案重做自测，再将示范中的人物、时间或条件改为自己的情境；解释改动后哪些词需要变化。</p><p><a href="/life/english/new-concept/book-4/unit-04/grammar">单元语法</a> · <a href="/life/english/new-concept/book-4/unit-04/vocabulary">单元单词</a> · <a href="/life/english/new-concept/book-4/unit-04/review">单元自测</a></p><p><a href="/life/english/new-concept/book-4/unit-04/lesson-029">上一课</a> · <a href="/life/english/new-concept/book-4/unit-04/overview">单元目录</a> · <a href="/life/english/new-concept/book-4/unit-04/lesson-031">下一课</a></p><hr><p>本站原创学习伴读：保留经典版课号和课名，讲解、例句与练习独立编写。重点词汇用于本页学习，不等同于教材全部生词表；教材课文、完整译文、原题与录音请配合自己的正版教材使用。</p>',41)])])}const b=t(r,[["render",i]]);export{u as __pageData,b as default};
